#!/usr/bin/env python3
"""
scripts/install_git_hooks.py
Installs Git pre-commit and pre-push hooks that run scripts/check_policy.py
to block accidental policy violations, unwhitelisted presets, or secret leaks.
"""

import os
import stat
import sys

WORKSPACE_ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
HOOKS_DIR = os.path.join(WORKSPACE_ROOT, ".git", "hooks")

HOOK_SCRIPT = """#!/bin/sh
# Auto-generated by scripts/install_git_hooks.py
echo "[CoverageMap Git Hook] Running Tier 1 Static Policy & Security Checker..."
if command -v python >/dev/null 2>&1; then
    python scripts/check_policy.py
elif command -v python3 >/dev/null 2>&1; then
    python3 scripts/check_policy.py
else
    echo "Error: Python interpreter not found in PATH."
    exit 1
fi
"""


def install_hooks() -> int:
    if not os.path.isdir(HOOKS_DIR):
        print(f"Error: .git/hooks directory not found at {HOOKS_DIR}")
        return 1

    for hook_name in ("pre-commit", "pre-push"):
        hook_path = os.path.join(HOOKS_DIR, hook_name)
        with open(hook_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(HOOK_SCRIPT)
        try:
            st = os.stat(hook_path)
            os.chmod(hook_path, st.st_mode | stat.S_IEXEC)
        except OSError:
            pass
        print(f"Installed Git hook: .git/hooks/{hook_name}")

    return 0


if __name__ == "__main__":
    sys.exit(install_hooks())
